import { all, get, put, remove } from './db.js';

const esc = (v='') => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (v, fallback=0) => Number.isFinite(Number(v)) ? Number(v) : fallback;
const fmt = (v, d=2) => new Intl.NumberFormat('es-AR',{minimumFractionDigits:0,maximumFractionDigits:d}).format(v||0);
const uid = () => (crypto.randomUUID ? crypto.randomUUID() : `dpms-${Date.now()}-${Math.random().toString(16).slice(2)}`);
const gradeFor = area => area == null || area <= 0 ? null : area <= 60 ? 'Mínimo' : area <= 130 ? 'Medio' : area <= 200 ? 'Elevado' : 'Superior';
const gradeRules = {
  'Mínimo': [{iug:1,tug:1,free:0,label:'Única: 1 IUG + 1 TUG'}],
  'Medio': [{iug:2,tug:1,free:0,label:'A: 2 IUG + 1 TUG'},{iug:1,tug:2,free:0,label:'B: 1 IUG + 2 TUG'}],
  'Elevado': [{iug:2,tug:3,free:0,label:'A: 2 IUG + 3 TUG'},{iug:3,tug:2,free:0,label:'B: 3 IUG + 2 TUG'}],
  'Superior': [{iug:2,tug:3,free:1,label:'A: 2 IUG + 3 TUG + 1 libre'},{iug:3,tug:2,free:1,label:'B: 3 IUG + 2 TUG + 1 libre'}]
};
const loadGuides = {
  generic: {label:'Carga general / sin clasificar', fp:0.90, fu:1, fs:1, note:'Valores iniciales genéricos. Verificar FP en placa/documentación y definir FU/FS según uso y proyecto.'},
  resistive: {label:'Resistencia eléctrica (termotanque, calefactor)', fp:1, fu:1, fs:1, note:'FP cercano a 1 para una resistencia convencional. FU=1 si se considera disponible a plena potencia. FS depende de si puede coincidir con otras cargas.'},
  motor: {label:'Motor eléctrico', fp:0.90, fu:1, fs:1, note:'FP=0,90 es solo provisional: reemplazar por dato de placa. FU=1 si se considera plena carga. FS depende de la operación simultánea prevista.'},
  pump: {label:'Bomba / presurizadora / riego', fp:0.90, fu:1, fs:1, note:'FP=0,90 es orientativo y debe verificarse en placa. El arranque/parada automática no justifica reducir FU por sí solo. FS=1 si puede funcionar junto con las demás cargas consideradas.'},
  hvac: {label:'Aire acondicionado / climatización', fp:0.90, fu:1, fs:1, note:'Usar FP y potencia de placa/fabricante. FU según régimen previsto y criterio de proyecto; FS según cantidad de equipos que pueden operar simultáneamente.'},
  specialLighting: {label:'Iluminación de uso especial (IUE)', fp:0.90, fu:1, fs:1, note:'Usar datos de los equipos cuando estén disponibles. No confundir este grupo de carga específica con la demanda reglamentaria de los circuitos IUE.'}
};
const circuitize = (label, bocas, demandPerCircuit, mode='perCircuit') => {
  const n=Math.ceil(Math.max(0,bocas)/15), rows=[]; let left=Math.max(0,bocas);
  for(let i=1;i<=n;i++){const b=Math.min(15,left);left-=b;rows.push({name:`${label} ${i}`,bocas:b,demandVA:mode==='perBoca'?b*demandPerCircuit:demandPerCircuit});}
  return rows;
};

export function calculateDPMS(input) {
  const c=input.circuits, area=num(input.scope?.applicationArea,0), grade=input.scope?.isDwelling ? gradeFor(area) : null;
  const ruleList=grade ? gradeRules[grade] : null;
  const variant=ruleList?.[Math.min(Math.max(0,num(input.scope?.variant,0)),ruleList.length-1)];
  const minIUG=variant?.iug||0, minTUG=variant?.tug||0;
  const auto={iugSimple:Math.ceil(num(c.iugSimpleBocas)/15),iugDerived:Math.ceil(num(c.iugDerivedBocas)/15),tug:Math.ceil(num(c.tugBocas)/15),iue:Math.ceil(num(c.iueBocas)/15),tue:Math.ceil(num(c.tueBocas)/15)};
  const actualIUG=Math.max(auto.iugSimple+auto.iugDerived,minIUG);
  const extraIUG=Math.max(0,actualIUG-auto.iugSimple-auto.iugDerived);
  const counts={iugSimple:auto.iugSimple+extraIUG,iugDerived:auto.iugDerived,tug:Math.max(auto.tug,minTUG),iue:auto.iue,tue:auto.tue};
  const iugSimpleVA=(2/3)*60*num(c.iugSimpleBocas), iugDerivedVA=2200*counts.iugDerived, tugVA=2200*counts.tug, iueVA=(2/3)*120*num(c.iueBocas), tueVA=3300*counts.tue;
  const circuitCount=Object.values(counts).reduce((a,b)=>a+b,0)+(variant?.free||0);
  const cs=circuitCount===2?1:circuitCount>=3&&circuitCount<=5?.7:circuitCount>=6&&circuitCount<=9?.6:circuitCount>=10?.5:null;
  const generalInstalledVA=iugSimpleVA+iugDerivedVA+tugVA+iueVA+tueVA, generalDemandVA=generalInstalledVA*(cs??1);
  const dedicated=(input.dedicated||[]).map(x=>{const activeW=num(x.quantity,1)*num(x.powerW),fp=Math.min(1,Math.max(.01,num(x.fp,.9))),apparentVA=activeW/fp,demandVA=apparentVA*num(x.fu,1)*num(x.fs,1);return {...x,activeW,apparentVA,demandVA};});
  const dedicatedDemandVA=dedicated.reduce((s,x)=>s+x.demandVA,0), totalVA=generalDemandVA+dedicatedDemandVA;
  const activeW=generalDemandVA*num(input.fp,.9)+dedicated.reduce((s,x)=>s+x.activeW*num(x.fu,1)*num(x.fs,1),0);
  const voltage=num(input.voltage,input.supply==='three'?380:220),currentA=input.supply==='three'?totalVA/(Math.sqrt(3)*voltage):totalVA/voltage;
  const circuitDetails=[
    ...circuitize('IUG sin tomacorrientes derivados',num(c.iugSimpleBocas),40,'perBoca').map(x=>({...x,kind:'general'})),
    ...circuitize('IUG con tomacorrientes derivados',num(c.iugDerivedBocas),2200).map(x=>({...x,kind:'general'})),
    ...circuitize('TUG',num(c.tugBocas),2200).map(x=>({...x,kind:'general'})),
    ...circuitize('IUE',num(c.iueBocas),80,'perBoca').map(x=>({...x,kind:'general'})),
    ...circuitize('TUE',num(c.tueBocas),3300).map(x=>({...x,kind:'general'})),
    ...dedicated.map((x,i)=>({name:`Carga específica ${i+1}: ${x.label||'Sin descripción'}`,kind:'specific',bocas:'—',quantity:x.quantity,powerW:x.powerW,activeW:x.activeW,fp:x.fp,fu:x.fu,fs:x.fs,apparentVA:x.apparentVA,demandVA:x.demandVA}))
  ];
  // Extra minimum IUG circuits required by the dwelling grade are shown explicitly.
  for(let i=1;i<=extraIUG;i++) circuitDetails.push({name:`IUG mínimo adicional ${i}`,kind:'general',bocas:0,demandVA:0,note:'Circuito mínimo exigido por grado; demanda según cargas efectivas'});
  const extraTUG=Math.max(0,counts.tug-auto.tug);
  for(let i=1;i<=extraTUG;i++) circuitDetails.push({name:`TUG mínimo adicional ${i}`,kind:'general',bocas:0,demandVA:0,note:'Circuito mínimo exigido por grado; demanda según cargas efectivas'});
  if(variant?.free) for(let i=1;i<=variant.free;i++) circuitDetails.push({name:`Circuito de libre elección ${i}`,kind:'general',bocas:0,demandVA:0,note:'Circuito adicional mínimo de libre elección'});
  circuitDetails.forEach(x=>{x.dpmsVA=x.kind==='specific'?x.demandVA:x.demandVA*(cs??1);});
  const minimum={grade,variant:variant?.label||null,requiredIUG:minIUG,requiredTUG:minTUG,actualIUG:counts.iugSimple+counts.iugDerived,actualTUG:counts.tug,requiredTotal:(variant?.iug||0)+(variant?.tug||0)+(variant?.free||0),actualTotal:circuitCount,compliant:grade?actualIUG>=minIUG&&counts.tug>=minTUG&&circuitCount>=((variant?.iug||0)+(variant?.tug||0)+(variant?.free||0)):null};
  return {breakdown:{iugSimpleVA,iugDerivedVA,tugVA,iueVA,tueVA,generalInstalledVA,generalDemandVA,dedicatedDemandVA},circuitCounts:counts,circuitCount,cs,dedicated,totalVA,activeW,voltage,currentA,apparentKVA:totalVA/1000,activeKW:activeW/1000,currentMethod:input.supply==='three'?'Equivalente trifásico equilibrado':'Monofásico',grade,applicationArea:area,minimum,circuitDetails,references:[
    {label:'AEA 90364-7-770:2026, 770.7 y Tabla 770.7.I',detail:'Máximo 15 bocas por circuito IUG, TUG, IUE y TUE.'},
    {label:'AEA 90364-7-770:2026, 770.8.1.1',detail:'Superficie de aplicación: cubierta + 50 % semicubierta.'},
    {label:'AEA 90364-7-770:2026, 770.8.3.1 y Tabla 770.8.I',detail:'Grados de electrificación de viviendas por superficie.'},
    {label:'AEA 90364-7-770:2026, 770.8.3.2 y Tabla 770.8.II',detail:'Cantidad mínima y distribución de circuitos IUG/TUG según grado.'},
    {label:'AEA 90364-7-770:2026, 770.9.1 y Tablas 770.9.I y 770.9.II',detail:'Demanda de referencia y simultaneidad de circuitos de uso general y especial.'},
    {label:'AEA 90364-7-770:2026, 770.9.2.1 y 770.9.3.1',detail:'Cargas específicas y determinación de corriente por línea.'}
  ]};
}

function detailMarkup(record){
  const r=record.result, i=record.input, p=record.propertySnapshot||{}, s=i.scope||{};
  const circuitRows=(r.circuitDetails||[]).map(x=>x.kind==='specific'?`<tr><td>${esc(x.name)}</td><td>${fmt(x.quantity,0)}</td><td>${fmt(x.activeW)} W</td><td>${fmt(x.apparentVA)} VA</td><td>${fmt(x.fp,2)}</td><td>${fmt(x.fu,2)}</td><td>${fmt(x.fs,2)}</td><td>${fmt(x.demandVA)} VA</td><td>${fmt(x.dpmsVA)} VA</td></tr>`:`<tr><td>${esc(x.name)}</td><td>${fmt(x.bocas,0)}</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>${fmt(x.demandVA)} VA</td><td>${fmt(x.dpmsVA)} VA</td></tr>`).join('');
    return `<div class="dpms-snapshot"><h3>Resultado guardado</h3><div class="dpms-kpis"><div><span>Potencia aparente</span><strong>${fmt(r.totalVA)} VA</strong></div><div><span>Potencia activa estimada</span><strong>${fmt(r.activeW)} W</strong></div><div><span>Corriente equivalente</span><strong>${fmt(r.currentA)} A</strong></div><div><span>Grado de electrificación</span><strong>${esc(r.grade||(s.isDwelling?'Falta superficie':'No aplica al alcance'))}</strong></div><div><span>Circuitos finales UG/UE</span><strong>${fmt(r.circuitCount,0)}</strong><small>FS ${r.cs==null?'—':fmt(r.cs,2)}</small></div></div><p><b>Inmueble:</b> ${esc(p.name||'Sin inmueble')} · ${esc(s.scopeLabel||'Alcance no especificado')} · ${fmt(r.applicationArea)} m² de aplicación</p><p><b>Suministro:</b> ${esc(i.supply==='three'?'Trifásico':'Monofásico')} · ${fmt(i.voltage)} V · FP general ${fmt(i.fp,2)}</p><div class="dpms-formula"><b>Expresión aplicada</b><div>DPMS = (Σ S<sub>UG/UE</sub> × FS) + Σ (P<sub>n</sub> / FP × FU × FS)</div><small>FS aplicado a ${fmt(r.circuitCount,0)} circuitos UG/UE: ${r.cs==null?'no definido':fmt(r.cs,2)}. Referencias: AEA 770.9.1, Tabla 770.9.II y 770.9.2.1.</small><div class="dpms-formula-values">${fmt(r.breakdown?.generalInstalledVA)} VA × ${r.cs==null?'—':fmt(r.cs,2)} = ${fmt(r.breakdown?.generalDemandVA)} VA; cargas específicas: ${fmt(r.breakdown?.dedicatedDemandVA)} VA.</div></div><h4>Detalle por circuito</h4><div class="dpms-table-wrap"><table class="data-table"><thead><tr><th>Circuito / carga</th><th>Bocas / cant.</th><th>Potencia activa</th><th>Potencia aparente</th><th>FP</th><th>FU</th><th>FS</th><th>Demanda base</th><th>Demanda DPMS</th></tr></thead><tbody>${circuitRows||'<tr><td colspan="9">Sin circuitos cargados</td></tr>'}</tbody></table></div><p class="muted">Guardado: ${new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(record.createdAt))} · Versión ${esc(record.modelVersion)}</p></div>`;
}

function reportDocument(title,job,client,identity,property,body){
  const rows=(label,value)=>value?`<p><b>${label}:</b> ${esc(value)}</p>`:'';
  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${esc(title)} - ${esc(job.code||job.name)}</title><link rel="stylesheet" href="styles.css"><style>body{padding:28px;color:#14243a}.report-head{border-bottom:2px solid #2b82bd;padding-bottom:14px;margin-bottom:20px}.report-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px 28px}.report-head h1{margin:0 0 6px}.report-meta{font-size:13px;color:#52677d}.dpms-snapshot{margin-top:16px}@media print{ @page{size:A4 portrait;margin:10mm} body{padding:0!important;color:#14243a}.report-head{break-inside:avoid}.dpms-table-wrap{overflow:visible!important;width:100%!important}.dpms-table-wrap .data-table{width:100%!important;min-width:0!important;max-width:100%!important;table-layout:fixed!important;border-collapse:collapse!important}.dpms-table-wrap .data-table th,.dpms-table-wrap .data-table td{white-space:normal!important;overflow-wrap:anywhere!important;word-break:normal!important;padding:4px 3px!important;font-size:7.2pt!important;line-height:1.25!important;vertical-align:top}.dpms-table-wrap .data-table thead{display:table-header-group}.dpms-table-wrap .data-table tr{break-inside:avoid;page-break-inside:avoid}.dpms-snapshot h4,.dpms-snapshot h3{break-after:avoid}.dpms-table-wrap .data-table th:nth-child(1),.dpms-table-wrap .data-table td:nth-child(1){width:20%}.dpms-table-wrap .data-table th:nth-child(2),.dpms-table-wrap .data-table td:nth-child(2){width:8%}.dpms-table-wrap .data-table th:nth-child(3),.dpms-table-wrap .data-table td:nth-child(3){width:12%}.dpms-table-wrap .data-table th:nth-child(4),.dpms-table-wrap .data-table td:nth-child(4){width:12%}.dpms-table-wrap .data-table th:nth-child(5),.dpms-table-wrap .data-table td:nth-child(5){width:5%}.dpms-table-wrap .data-table th:nth-child(6),.dpms-table-wrap .data-table td:nth-child(6){width:5%}.dpms-table-wrap .data-table th:nth-child(7),.dpms-table-wrap .data-table td:nth-child(7){width:5%}.dpms-table-wrap .data-table th:nth-child(8),.dpms-table-wrap .data-table td:nth-child(8){width:16%}.dpms-table-wrap .data-table th:nth-child(9),.dpms-table-wrap .data-table td:nth-child(9){width:17%}}</style></head><body><header class="report-head"><h1>${esc(title)}</h1><h2>${esc(job.code||job.name||'Trabajo')}</h2><div class="report-grid"><section><h3>Cliente</h3>${rows('Nombre / razón social',client.name||[client.firstName,client.lastName].filter(Boolean).join(' '))}${rows('Documento / CUIT',client.document||client.taxId)}${rows('Teléfono',client.phone)}${rows('Email',client.email)}${rows('Domicilio',client.address)}${rows('Localidad',client.locality)}${rows('Provincia',client.province)}</section><section><h3>Profesional interviniente</h3>${rows('Nombre / razón social',identity.name)}${rows('Nombre comercial',identity.tradeName)}${rows('CUIT / DNI',identity.taxId)}${rows('Teléfono',identity.phone)}${rows('Email',identity.email)}${rows('Domicilio',identity.address)}</section></div><div class="report-meta">Emitido: ${new Intl.DateTimeFormat('es-AR',{dateStyle:'long',timeStyle:'short'}).format(new Date())}</div>${property?`<section><h3>Inmueble</h3>${rows('Identificación',property.name)}${rows('Domicilio',property.address)}${rows('Localidad',property.locality)}${rows('Provincia',property.province)}</section>`:''}</header>${body}</body></html>`;
}

export async function renderDPMS(root, job, goBack) {
  const [savedAll,properties,clients,identityRecord]=await Promise.all([all('dpms_calculations'),all('properties'),all('clients'),get('settings','identity')]);
  const reportClient=clients.find(c=>c.id===job.clientId)||{};
  const reportIdentity=identityRecord?.value||{};
  const saved=savedAll.filter(x=>x.jobId===job.id).sort((a,b)=>(b.updatedAt||b.createdAt).localeCompare(a.updatedAt||a.createdAt));
  const property=properties.find(p=>p.id===job.propertyId)||null;
  const propertyType=String(property?.type||'').trim().toLocaleLowerCase('es');
  const dwelling=['house','apartment','ph','dwelling','residential','vivienda','casa','departamento','unidad funcional','departamento / unidad funcional','vivienda unifamiliar'].includes(propertyType) || propertyType.startsWith('departamento') || propertyType.startsWith('unidad funcional');
  const buildingType=['building','edificio'].includes(propertyType);
  const unitLike=['apartment','ph','departamento','unidad funcional','departamento / unidad funcional'].includes(propertyType) || propertyType.startsWith('departamento') || propertyType.startsWith('unidad funcional');
  const initialScopeMode=unitLike?'unit':'full';
  root.innerHTML=`<div class="page-heading"><div><p class="eyebrow">CÁLCULO TÉCNICO · ${esc(job.code)}</p><h1>Demanda de potencia máxima simultánea</h1><p class="muted">Cálculo asociado a ${esc(job.name)}.</p></div><div class="heading-actions"><button class="secondary" id="dpms-back">← Volver al trabajo</button></div></div>
  <section id="dpms-current" class="panel" style="margin-bottom:18px"></section>
  <form id="dpms-form" class="panel dpms-form" ${saved.length?'hidden':''}><div class="section-title"><div><h2>Inmueble y alcance</h2><p class="muted">Los datos se recuperan de la ficha del inmueble asociado al trabajo.</p></div></div>
  <div class="dpms-property-summary"><b>${esc(property?.name||'Este trabajo no tiene inmueble asociado')}</b><span>${esc(property?.type||'')}</span><span>Superficie cubierta: ${property?.coveredArea!=null?fmt(property.coveredArea)+' m²':'No cargada'}</span><span>Semicubierta: ${property?.semiCoveredArea!=null?fmt(property.semiCoveredArea)+' m²':'No cargada'}</span><span>Plantas: ${property?.floors||'—'}</span><span>Unidades: ${property?.unitCount||'—'}</span></div>
  <div class="form-grid"><label>Alcance del cálculo<select name="scopeMode"><option value="full" ${initialScopeMode==='full'?'selected':''}>Inmueble completo</option><option value="unit" ${initialScopeMode==='unit'?'selected':''}>Unidad funcional / departamento / PH</option><option value="sector">Sector o instalación parcial</option></select></label><label>Identificación de unidad / sector<input name="scopeLabel" value="${esc(property?.unitLabel||'')}" placeholder="Ej. UF 2, planta alta, local 3"></label><label>Superficie cubierta considerada (m²)<input name="coveredArea" type="number" min="0" step="0.01" value="${(initialScopeMode==='unit'?(property?.unitCoveredArea??property?.coveredArea):property?.coveredArea)??''}"></label><label>Superficie semicubierta considerada (m²)<input name="semiCoveredArea" type="number" min="0" step="0.01" value="${(initialScopeMode==='unit'?(property?.unitSemiCoveredArea??property?.semiCoveredArea):property?.semiCoveredArea)??''}"></label></div>
  <p class="dpms-note">Superficie de aplicación = cubierta + 50 % semicubierta (AEA 770.8.1.1). Para sectores parciales, ingresá la superficie correspondiente al alcance calculado. Los valores editados aquí quedan registrados en esta versión y no modifican la ficha del inmueble.</p>
  <div id="grade-panel"></div>
  <div class="section-title"><div><h2>Datos del suministro</h2><p class="muted">Los parámetros normativos se muestran como referencia y no son editables.</p></div></div><div class="form-grid"><label>Tipo de suministro<select name="supply"><option value="single">Monofásico</option><option value="three">Trifásico</option></select></label><label>Tensión nominal (V)<input name="voltage" type="number" min="1" step="1" value="220" required></label><label>FP general de referencia<input name="fp" type="number" min="0.01" max="1" step="0.01" value="0.90" required></label></div>
  <div class="section-title"><div><h2>Circuitos de uso general y especial</h2><p class="muted">Ingresá bocas. La cantidad de circuitos se determina automáticamente.</p></div></div><div class="dpms-table-wrap"><table class="data-table"><thead><tr><th>Tipo de circuito</th><th>Bocas</th><th>Circuitos calculados</th><th>Demanda de referencia</th></tr></thead><tbody>
  <tr><td>IUG sin tomacorrientes derivados</td><td><input name="iugSimpleBocas" type="number" min="0" step="1" value="0"></td><td><output data-circuits="iugSimple">0</output></td><td>2/3 × bocas × 60 VA</td></tr><tr><td>IUG con tomacorrientes derivados</td><td><input name="iugDerivedBocas" type="number" min="0" step="1" value="0"></td><td><output data-circuits="iugDerived">0</output></td><td>2.200 VA/circuito</td></tr><tr><td>TUG</td><td><input name="tugBocas" type="number" min="0" step="1" value="0"></td><td><output data-circuits="tug">0</output></td><td>2.200 VA/circuito</td></tr><tr><td>IUE</td><td><input name="iueBocas" type="number" min="0" step="1" value="0"></td><td><output data-circuits="iue">0</output></td><td>2/3 × bocas × 120 VA</td></tr><tr><td>TUE</td><td><input name="tueBocas" type="number" min="0" step="1" value="0"></td><td><output data-circuits="tue">0</output></td><td>3.300 VA/circuito</td></tr></tbody></table></div>
  <p class="dpms-note">AEA 770.7 y Tabla 770.7.I: máximo 15 bocas por circuito para IUG, TUG, IUE y TUE. Los valores de demanda son mínimos de referencia; si se conocen cargas mayores, se considera la demanda mayor.</p>
  <div class="section-title"><div><h2>Cargas específicas</h2><p class="muted">Cada carga conserva potencia, FP, FU y FS propios. Podés elegir un tipo para cargar valores iniciales orientativos.</p></div><button type="button" class="secondary" id="add-dedicated">＋ Agregar carga</button></div>
  <details class="dpms-guide"><summary>Guía orientativa: FP, FU y FS</summary><div class="dpms-guide-content"><p><b>FP — Factor de potencia:</b> relación entre potencia activa y aparente. <code>FP = W / VA</code>. Priorizar el valor de placa o documentación del fabricante. No es un valor universal por artefacto.</p><p><b>FU — Factor de utilización:</b> proporción de la potencia nominal que se considera utilizada en la condición de diseño. Si se considera que trabaja a plena potencia, FU = 1. No reducirlo automáticamente por ciclos de encendido y apagado.</p><p><b>FS — Factor de simultaneidad:</b> proporción de cargas del grupo que se considera que pueden funcionar al mismo tiempo. Depende de la instalación, controles, interbloqueos y criterio del proyectista. No se deduce solamente del nombre del equipo.</p><p class="dpms-guide-warning">Los valores sugeridos por el programa son orientativos, no exigencias normativas ni sustituyen la placa, documentación técnica o criterio del proyectista. En la cláusula AEA 90364-7-770:2026 770.9.2.1, FU y FS de cargas específicas se establecen según el criterio del proyectista.</p><div class="dpms-guide-grid"><div><b>FP</b><span>Fabricante / placa</span></div><div><b>FU</b><span>Régimen de utilización previsto</span></div><div><b>FS</b><span>Posibilidad real de simultaneidad</span></div></div></div></details><div id="dedicated-list"></div>
  <div class="section-title"><div><h2>Resultado</h2><p class="muted">Resumen de potencia, corriente y grado de electrificación.</p></div></div><div id="dpms-results" class="dpms-results"></div><div class="section-title"><div><h2>Detalle individual por circuito</h2><p class="muted">Distribución automática de bocas hasta 15 por circuito.</p></div></div><div id="circuit-detail"></div>
  <div class="modal-actions"><button type="submit" class="primary" id="dpms-save">Guardar cálculo</button><button type="button" class="secondary" id="dpms-cancel-edit">Cancelar</button></div></form>
  <section class="panel voltage-drop-panel" id="voltage-drop-panel" style="margin-top:18px"><div class="section-title"><div><p class="eyebrow">ALIMENTADOR TP–TS</p><h2>Dimensionamiento por caída de tensión</h2><p class="muted">Los datos de demanda se toman automáticamente del cálculo DPMS vigente. Seleccioná únicamente el tipo de tendido y la longitud real TP–TS.</p></div></div>
  <div class="form-grid"><label>Tipo de tendido<select id="vd-installation"><option value="aerial">Aéreo</option><option value="underground">Subterráneo</option></select></label><label>Longitud TP–TS (m, recorrido real)<input id="vd-distance" type="number" min="0.1" step="0.1" placeholder="Longitud real en metros"></label><label>Caída máxima objetivo (%)<input id="vd-limit" type="number" min="0.1" step="0.1" value="3"></label></div>
  <div id="vd-dpms-source" class="dpms-note"></div>
  <div id="vd-results" class="dpms-results" aria-live="polite"></div>
  <p class="dpms-note">Perfiles de referencia del Excel: aéreo 30 °C ambiente, método 35-E; subterráneo 20 °C suelo, método 73-D2 y resistividad térmica del suelo 2,5 K·m/W. Aislación PVC y un circuito en el conducto como perfil inicial. La selección de sección por caída de tensión se combina con la sección mínima asociada a la protección del pilar, igual que en la hoja ALIMENTADOR.</p>
  <p class="dpms-warning">Este cálculo reproduce el dimensionamiento por caída de tensión del Excel. No verifica por sí solo la ampacidad real, cortocircuito, agrupamiento ni coordinación completa; esas comprobaciones dependen de las condiciones efectivas de instalación.</p>
  <div class="modal-actions"><button type="button" class="primary" id="vd-save">Guardar cálculo TP–TS</button><button type="button" class="secondary" id="vd-clear">Restablecer</button></div><div id="vd-history"></div></section>
  <section class="panel" style="margin-top:18px"><div class="section-title"><div><h2>Historial de cálculos</h2><p class="muted">Consultá registros anteriores. Editar actualiza el mismo registro, sin crear copias.</p></div><button type="button" class="secondary" id="dpms-new">＋ Nuevo cálculo</button></div><div id="dpms-history"></div></section>`;
  root.querySelector('#dpms-back').onclick=goBack;
  const form=root.querySelector('#dpms-form'),dedicatedList=root.querySelector('#dedicated-list'),results=root.querySelector('#dpms-results'),gradePanel=root.querySelector('#grade-panel'),circuitDetail=root.querySelector('#circuit-detail');
  let dedicated=[];
  let editingId=null;
  let selectedDPMSId=saved[0]?.id||null;
  const currentPanel=root.querySelector('#dpms-current');
  const vdPanel=root.querySelector('#voltage-drop-panel');
  const vdInstallation=vdPanel.querySelector('#vd-installation'),vdDistance=vdPanel.querySelector('#vd-distance'),vdLimit=vdPanel.querySelector('#vd-limit');
  let vdSaved=(await get('settings',`voltage-drop:${job.id}`))?.value||[];
  const vdSections=[2.5,4,6,10,16,25,35,50,70,95,120];
  const vdFmt=(v,d=2)=>new Intl.NumberFormat('es-AR',{minimumFractionDigits:0,maximumFractionDigits:d}).format(Number(v)||0);
  function vdProtection(current){
    if(current<=16)return {rating:16,minSection:2.5};
    if(current<=20)return {rating:20,minSection:4};
    if(current<=25)return {rating:25,minSection:4};
    if(current<=32)return {rating:32,minSection:6};
    if(current<=40)return {rating:40,minSection:10};
    if(current<=63)return {rating:63,minSection:16};
    return {rating:null,minSection:null};
  }
  function vdCurrentDPMS(){
    const rec=saved.find(x=>x.id===selectedDPMSId)||saved[0];
    if(!rec)return null;
    const r=rec.result||{},i=rec.input||{};
    const voltage=Number(r.voltage)||Number(i.voltage)||(i.supply==='three'?380:220);
    return {recordId:rec.id,recordDate:rec.updatedAt||rec.createdAt,supply:i.supply==='three'?'Trifásico':'Monofásico',voltage,totalVA:Number(r.totalVA)||0,activeW:Number(r.activeW)||0,current:Number(r.currentA)||0,fp:Number(i.fp)||0.9};
  }
  function vdCalcMaterial(current,voltage,distance,limit,installation,material,three){
    const aerial=installation==='aerial',temp=aerial?30:20,method=aerial?'35-E':'73-D2';
    const rho20=material==='cu'?.0175:.0282,alpha=material==='cu'?.00393:.00403;
    const rho=rho20*(1+alpha*(temp-20)),protection=vdProtection(current);
    const calcDrop=section=>((three?Math.sqrt(3):2)*current*distance*rho/section/voltage)*100;
    const table=vdSections.map(section=>({section,drop:calcDrop(section),compliant:calcDrop(section)<=limit}));
    const dropSection=table.find(x=>x.compliant)?.section||null;
    const section=dropSection&&protection.minSection?Math.max(dropSection,protection.minSection):null;
    const finalDrop=section?calcDrop(section):null;
    return {material,temp,method,rho,protection,table,dropSection,section,drop:finalDrop,percent:finalDrop,voltageDropV:finalDrop==null?null:finalDrop*voltage/100,receivingVoltage:finalDrop==null?null:voltage*(1-finalDrop/100)};
  }
  function vdPaint(){
    const d=Number(vdDistance.value),limit=Number(vdLimit.value),dp=vdCurrentDPMS(),three=dp?.supply==='Trifásico';
    const aerial=vdInstallation.value==='aerial',temp=aerial?30:20,method=aerial?'35-E':'73-D2';
    const valid=!!dp&&dp.totalVA>0&&dp.current>0&&dp.voltage>0&&d>0&&limit>0;
    vdPanel.querySelector('#vd-dpms-source').innerHTML=`<b>Datos tomados del último DPMS guardado:</b> ${dp?`${vdFmt(dp.totalVA)} VA (${vdFmt(dp.totalVA/1000,3)} kVA) · ${vdFmt(dp.activeW)} W · ${vdFmt(dp.current)} A · ${dp.supply} · ${vdFmt(dp.voltage)} V · FP ${vdFmt(dp.fp,2)} · ${new Date(dp.recordDate).toLocaleString('es-AR')}`:'No hay un cálculo DPMS guardado para este trabajo.'}`;
    if(!valid){vdPanel.querySelector('#vd-results').innerHTML='<p class="dpms-warning">Primero guardá un cálculo DPMS con demanda mayor que cero. Después ingresá la longitud real TP–TS y el criterio de caída.</p>';return null;}
    const cu=vdCalcMaterial(dp.current,dp.voltage,d,limit,vdInstallation.value,'cu',three),al=vdCalcMaterial(dp.current,dp.voltage,d,limit,vdInstallation.value,'al',three);
    const protection=cu.protection.rating?`${cu.protection.rating} A`:'REVISAR ALIMENTACIÓN';
    const render=(label,x)=>`<div class="dpms-kpis"><div><span>Sección ${label}</span><strong>${x.section?`${vdFmt(x.section)} mm²`:'REVISAR'}</strong><small>Caída ${x.percent==null?'—':vdFmt(x.percent,3)+' %'}</small></div><div><span>Caída de tensión</span><strong>${x.voltageDropV==null?'—':vdFmt(x.voltageDropV,2)+' V'}</strong><small>Tensión TS ${x.receivingVoltage==null?'—':vdFmt(x.receivingVoltage,2)+' V'}</small></div><div><span>Sección mínima por protección</span><strong>${x.protection.minSection==null?'Revisar':vdFmt(x.protection.minSection)+' mm²'}</strong><small>Protección pilar: ${protection}</small></div><div><span>Perfil aplicado</span><strong>${vdFmt(x.temp,0)} °C</strong><small>${x.method} · PVC</small></div></div>`;
    const table=(label,x)=>`<h4>Comparación de secciones ${label}</h4><div class="dpms-table-wrap"><table class="data-table"><thead><tr><th>Sección (mm²)</th><th>Caída (%)</th><th>Resultado</th></tr></thead><tbody>${x.table.map(t=>`<tr><td>${vdFmt(t.section)}</td><td>${vdFmt(t.drop,3)} %</td><td>${t.compliant?'Cumple caída':'Supera objetivo'}</td></tr>`).join('')}</tbody></table></div>`;
    vdPanel.querySelector('#vd-results').innerHTML=`<div class="dpms-kpis"><div><span>Protección termomagnética de referencia</span><strong>${protection}</strong><small>Según corriente DPMS; mínimo 16 A</small></div><div><span>Longitud TP–TS</span><strong>${vdFmt(d)} m</strong><small>Longitud de recorrido, solo ida</small></div><div><span>Caída objetivo</span><strong>${vdFmt(limit,2)} %</strong><small>Criterio de diseño configurable</small></div><div><span>Tipo de tendido</span><strong>${aerial?'Aéreo':'Subterráneo'}</strong><small>${aerial?'30 °C ambiente':'20 °C suelo · 2,5 K·m/W'}</small></div></div><h3>Dimensionamiento en cobre</h3>${render('Cu',cu)}${table('Cu',cu)}<h3>Dimensionamiento en aluminio</h3>${render('Al',al)}${table('Al',al)}<p class="dpms-note">Fórmula replicada de ALIMENTADOR: ΔU% = ${three?'√3':'2'} × I × L × ρ(T) / (S × U) × 100. La resistencia se corrige por temperatura. El resultado final toma la mayor sección entre la requerida por caída y la mínima asociada a la protección.</p>`;
    return {dpms:dp,installation:vdInstallation.value,distance:d,limit,cu,al,protection:cu.protection};
  }
  vdDistance.addEventListener('input',vdPaint);vdLimit.addEventListener('input',vdPaint);vdInstallation.addEventListener('change',vdPaint);
  form.addEventListener('input',()=>vdPaint());
  form.addEventListener('change',()=>vdPaint());
  root.querySelector('#vd-save').onclick=async()=>{
    const result=vdPaint();if(!result){alert('Completá y guardá primero el cálculo DPMS, e ingresá longitud y caída objetivo.');return;}
    vdSaved.unshift({id:uid(),createdAt:new Date().toISOString(),input:{installation:result.installation,distance:result.distance,limit:result.limit},result});
    await put('settings',{key:`voltage-drop:${job.id}`,value:vdSaved});vdRenderHistory();
  };
  root.querySelector('#vd-clear').onclick=()=>{vdInstallation.value='aerial';vdDistance.value='';vdLimit.value=3;vdPaint();};
  function vdReportMarkup(record){
    if(!record)return `<section class="dpms-snapshot"><h2>Alimentador TP–TS · Caída de tensión</h2><p>No hay un cálculo de caída de tensión guardado asociado a esta versión del DPMS. Para incorporarlo, guardá el cálculo TP–TS después de guardar el DPMS vigente.</p></section>`;
    const x=record.result,dp=x.dpms,cu=x.cu,al=x.al;
    const materialName=m=>m==='cu'?'Cobre':'Aluminio';
    const fmtCell=(v,d=2)=>v==null?'—':`${vdFmt(v,d)}`;
    const materialRows=[['Cobre',cu],['Aluminio',al]].map(([name,m])=>`<tr><td>${name}</td><td>${m.section?`${vdFmt(m.section)} mm²`:'No determinada'}</td><td>${fmtCell(m.voltageDropV)} V</td><td>${fmtCell(m.percent,3)} %</td><td>${fmtCell(m.receivingVoltage)} V</td><td>${m.protection?.minSection?`${vdFmt(m.protection.minSection)} mm²`:'A verificar'}</td></tr>`).join('');
    const protection=x.protection?.rating?`${vdFmt(x.protection.rating)} A`:'A verificar según corriente y condiciones de instalación';
    const sameDPMS=dp?.recordId===saved[0]?.id;
    return `<section class="dpms-snapshot"><h2>Alimentador TP–TS · Dimensionamiento por caída de tensión</h2><p><b>Vinculación:</b> ${sameDPMS?'Cálculo DPMS vigente':'Cálculo DPMS guardado asociado al dimensionamiento'} · ${dp?.recordDate?new Date(dp.recordDate).toLocaleString('es-AR'):''}</p><div class="report-grid"><div><b>Tipo de tendido:</b> ${x.installation==='aerial'?'Aéreo':'Subterráneo'}</div><div><b>Longitud TP–TS:</b> ${vdFmt(x.distance)} m (recorrido)</div><div><b>Caída máxima objetivo:</b> ${vdFmt(x.limit,2)} %</div><div><b>Interruptor termomagnético de referencia:</b> ${protection}</div><div><b>Demanda DPMS utilizada:</b> ${vdFmt(dp?.totalVA)} VA</div><div><b>Corriente de proyecto:</b> ${vdFmt(dp?.current)} A</div><div><b>Potencia activa:</b> ${vdFmt(dp?.activeW)} W</div><div><b>Suministro:</b> ${esc(dp?.supply||'—')} · ${vdFmt(dp?.voltage)} V · FP ${vdFmt(dp?.fp,2)}</div></div><h3>Resultado de dimensionamiento por material</h3><div class="dpms-table-wrap"><table class="data-table"><thead><tr><th>Conductor</th><th>Sección calculada</th><th>Caída resultante</th><th>Caída (%)</th><th>Tensión estimada TS</th><th>Sección mínima por protección</th></tr></thead><tbody>${materialRows}</tbody></table></div><p><b>Perfil de cálculo:</b> ${x.installation==='aerial'?'Aéreo · 30 °C · método 35-E':'Subterráneo · 20 °C · método 73-D2 · resistividad térmica del suelo 2,5 K·m/W'} · Aislación PVC.</p><p><b>Nota:</b> el interruptor indicado es una referencia calculada a partir de la corriente DPMS y no reemplaza la selección/verificación final. Confirmar ampacidad, cortocircuito, agrupamiento, coordinación y condiciones reales de instalación. La sección informada está expresada en mm² (no en diámetro).</p></section>`;
  }
  function vdRenderHistory(){
    const box=vdPanel.querySelector('#vd-history');
    box.innerHTML=vdSaved.length?`<h3>Historial de alimentadores TP–TS</h3>${vdSaved.map(x=>`<div class="history-row"><div><strong>${new Date(x.createdAt).toLocaleString('es-AR')}</strong><small>${x.input.installation==='aerial'?'Aéreo':'Subterráneo'} · ${vdFmt(x.input.distance)} m · DPMS ${vdFmt(x.result?.dpms?.totalVA)} VA · ITM ${x.result?.protection?.rating?vdFmt(x.result.protection.rating)+' A':'A verificar'} · Cu ${x.result?.cu?.section?vdFmt(x.result.cu.section)+' mm²':'Revisar'} · Al ${x.result?.al?.section?vdFmt(x.result.al.section)+' mm²':'Revisar'}</small></div><div class="history-actions"><button type="button" class="secondary" data-vd-view="${esc(x.id)}">Ver / cargar</button><button type="button" class="danger" data-vd-delete="${esc(x.id)}">Eliminar</button></div></div>`).join('')}`:'<p class="muted">Todavía no hay cálculos TP–TS guardados.</p>';
    box.querySelectorAll('[data-vd-view]').forEach(btn=>btn.onclick=()=>{
      const item=vdSaved.find(x=>x.id===btn.dataset.vdView);if(!item)return;
      vdInstallation.value=item.input.installation;vdDistance.value=item.input.distance;vdLimit.value=item.input.limit;
      selectedDPMSId=item.result?.dpms?.recordId||selectedDPMSId;paintCurrent();showForm(false);vdShowSaved(item);vdPanel.scrollIntoView({behavior:'smooth',block:'start'});
    });
    box.querySelectorAll('[data-vd-delete]').forEach(btn=>btn.onclick=async()=>{
      const item=vdSaved.find(x=>x.id===btn.dataset.vdDelete);if(!item)return;
      const stamp=new Date(item.createdAt).toLocaleString('es-AR');
      if(!confirm(`¿Eliminar definitivamente SOLO este dimensionamiento TP–TS (${stamp})? El cálculo DPMS asociado y los demás dimensionamientos no se modificarán.`))return;
      btn.disabled=true;
      try{
        vdSaved=vdSaved.filter(x=>x.id!==item.id);
        await put('settings',{key:`voltage-drop:${job.id}`,value:vdSaved});
        const next=vdSaved.find(x=>x.result?.dpms?.recordId===selectedDPMSId);
        if(next){vdInstallation.value=next.input.installation;vdDistance.value=next.input.distance;vdLimit.value=next.input.limit;vdShowSaved(next);}
        else{vdPaint();}
        vdRenderHistory();
      }catch(err){
        vdSaved.push(item);vdSaved.sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));vdRenderHistory();
        alert('No se pudo eliminar el dimensionamiento. El registro se conservó. Detalle: '+(err?.message||err));
      }
    });
  }
  function vdShowSaved(item){
    const x=item.result,dp=x.dpms;
    const protection=x.protection||x.cu?.protection||{};
    const itm=protection.rating?`${vdFmt(protection.rating)} A`:'A verificar según corriente y condiciones de instalación';
    const one=(name,m)=>`<div class="dpms-kpis"><div><span>Sección final ${name}</span><strong>${m.section?`${vdFmt(m.section)} mm²`:'REVISAR'}</strong><small>Sección mínima por protección: ${m.protection?.minSection==null?'A verificar':vdFmt(m.protection.minSection)+' mm²'}</small></div><div><span>Caída resultante</span><strong>${m.voltageDropV==null?'—':vdFmt(m.voltageDropV,2)+' V'}</strong><small>${m.percent==null?'—':vdFmt(m.percent,3)+' %'}</small></div><div><span>Tensión estimada TS</span><strong>${m.receivingVoltage==null?'—':vdFmt(m.receivingVoltage,2)+' V'}</strong><small>Material: ${name}</small></div></div>`;
    vdPanel.querySelector('#vd-dpms-source').innerHTML=`<b>DPMS asociado:</b> ${new Date(dp.recordDate||item.createdAt).toLocaleString('es-AR')} · ${vdFmt(dp.totalVA)} VA · ${vdFmt(dp.current)} A · ${esc(dp.supply||'—')} · ${vdFmt(dp.voltage)} V · FP ${vdFmt(dp.fp,2)}.`;
    vdPanel.querySelector('#vd-results').innerHTML=`<h3>Resultado final guardado · ${x.installation==='aerial'?'Aéreo':'Subterráneo'}</h3><div class="dpms-kpis"><div><span>Interruptor termomagnético (ITM) de referencia</span><strong>${itm}</strong><small>Derivado de la corriente del DPMS asociado</small></div><div><span>Longitud TP–TS</span><strong>${vdFmt(x.distance)} m</strong><small>Recorrido real, solo ida</small></div><div><span>Caída máxima objetivo</span><strong>${vdFmt(x.limit,2)} %</strong><small>Criterio de diseño</small></div><div><span>Tipo de tendido</span><strong>${x.installation==='aerial'?'Aéreo':'Subterráneo'}</strong><small>${x.installation==='aerial'?'30 °C · método 35-E':'20 °C · método 73-D2'}</small></div></div><h4>Resultado en cobre</h4>${one('Cu',x.cu)}<h4>Resultado en aluminio</h4>${one('Al',x.al)}<p class="dpms-note">Este es el resultado histórico guardado y se muestra completo sin recalcular. El ITM es una referencia basada en la corriente DPMS; la selección definitiva requiere verificar ampacidad, cortocircuito, agrupamiento y coordinación según las condiciones reales.</p>`;
  }
  function showForm(show){form.hidden=!show;currentPanel.hidden=show;}
  function paintCurrent(){const latest=saved.find(x=>x.id===selectedDPMSId)||saved[0];if(!latest){currentPanel.innerHTML='<p class="muted">Todavía no hay un cálculo guardado para este trabajo.</p>';currentPanel.hidden=true;form.hidden=false;return;}currentPanel.hidden=false;currentPanel.innerHTML=`<div class="section-title"><div><p class="eyebrow">CÁLCULO ACTUAL</p><h2>Cálculo seleccionado</h2><p class="muted">${new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(latest.updatedAt||latest.createdAt))}</p></div><div class="history-actions"><button type="button" class="primary" id="dpms-edit-current">Editar cálculo</button><button type="button" class="secondary" id="dpms-print-current">Exportar / Imprimir</button></div></div>${detailMarkup(latest)}`;currentPanel.querySelector('#dpms-edit-current').onclick=()=>restoreSaved(latest.id,true);currentPanel.querySelector('#dpms-print-current').onclick=()=>{const w=window.open('','_blank');if(!w){alert('El navegador bloqueó la ventana de impresión. Permití ventanas emergentes para este sitio.');return;}const attached=vdSaved.find(x=>x.result?.dpms?.recordId===latest.id)||null;const reportBody=detailMarkup(latest)+vdReportMarkup(attached);w.document.write(reportDocument('Informe DPMS',job,reportClient,reportIdentity,property,reportBody));w.document.close();w.focus();w.onload=()=>w.print();};}
  root.querySelector('#dpms-new').onclick=()=>startNew();
  root.querySelector('#dpms-cancel-edit').onclick=()=>{editingId=null;paintCurrent();showForm(false);};
  function startNew(){editingId=null;form.reset();form.elements.voltage.value=220;form.elements.fp.value=.90;form.elements.scopeMode.value=initialScopeMode;form.elements.scopeLabel.value=property?.unitLabel||'';form.elements.coveredArea.value=(initialScopeMode==='unit'?(property?.unitCoveredArea??property?.coveredArea):property?.coveredArea)??'';form.elements.semiCoveredArea.value=(initialScopeMode==='unit'?(property?.unitSemiCoveredArea??property?.semiCoveredArea):property?.semiCoveredArea)??'';dedicated=[];renderDedicated();calculate();form.querySelector('#dpms-save').textContent='Guardar cálculo';showForm(true);form.scrollIntoView({behavior:'smooth',block:'start'});}
  function read(){const v=Object.fromEntries(new FormData(form));const mode=v.scopeMode;const unitMode=mode==='unit';const propertyCovered=unitMode?(property?.unitCoveredArea??(unitLike?property?.coveredArea:null)):property?.coveredArea;const propertySemi=unitMode?(property?.unitSemiCoveredArea??(unitLike?property?.semiCoveredArea:null)):property?.semiCoveredArea;const covered=v.coveredArea===''?num(propertyCovered,0):num(v.coveredArea);const semi=v.semiCoveredArea===''?num(propertySemi,0):num(v.semiCoveredArea);const residentialUnit=dwelling||(buildingType&&unitMode);const scope={scopeMode:mode,scopeLabel:v.scopeLabel|| (mode==='full'?'Inmueble completo':mode==='unit'?'Unidad funcional':'Sector / instalación parcial'),coveredArea:covered,semiCoveredArea:semi,applicationArea:covered+semi*.5,isDwelling:residentialUnit&&mode!=='sector',variant:num(v.gradeVariant,0)};return {supply:v.supply,voltage:num(v.voltage,v.supply==='three'?380:220),fp:num(v.fp,.9),scope,circuits:{iugSimpleBocas:num(v.iugSimpleBocas),iugDerivedBocas:num(v.iugDerivedBocas),tugBocas:num(v.tugBocas),iueBocas:num(v.iueBocas),tueBocas:num(v.tueBocas)},dedicated};}
  function renderDedicated(){
    dedicatedList.innerHTML=dedicated.map((d,i)=>{const guide=loadGuides[d.category||'generic'];return `<div class="dpms-load-card" data-index="${i}"><div class="dpms-load-row"><label>Tipo de carga<select data-k="category">${Object.entries(loadGuides).map(([k,g])=>`<option value="${k}" ${(d.category||'generic')===k?'selected':''}>${esc(g.label)}</option>`).join('')}</select></label><label>Descripción / equipo<input data-k="label" value="${esc(d.label)}" placeholder="Ej. Bomba presurizadora 1"></label><label>Cantidad<input data-k="quantity" type="number" min="1" value="${d.quantity}"></label><label>Potencia unitaria (W)<input data-k="powerW" type="number" min="0" step="1" value="${d.powerW}"></label><label>FP<input data-k="fp" type="number" min="0.01" max="1" step="0.01" value="${d.fp}" title="Factor de potencia: priorizar placa o fabricante"></label><label>FU<input data-k="fu" type="number" min="0" max="1" step="0.01" value="${d.fu}" title="Factor de utilización: según régimen de uso"></label><label>FS<input data-k="fs" type="number" min="0" max="1" step="0.01" value="${d.fs}" title="Factor de simultaneidad: según cargas que pueden operar juntas"></label><button type="button" class="danger" data-remove="${i}">Quitar</button></div><p class="dpms-load-hint">${esc(guide.note)} ${d.isEstimated?' <b>Valores iniciales sugeridos; revisar antes de cerrar el cálculo.</b>':''}</p></div>`;}).join('')||'<p class="muted">No agregaste cargas específicas.</p>';
    dedicatedList.querySelectorAll('[data-k]').forEach(el=>el.addEventListener('input',()=>{const idx=Number(el.closest('[data-index]').dataset.index),item=dedicated[idx];if(el.dataset.k==='category'){const g=loadGuides[el.value];item.category=el.value;item.fp=g.fp;item.fu=g.fu;item.fs=g.fs;item.isEstimated=true;renderDedicated();calculate();return;}item[el.dataset.k]=el.type==='number'?num(el.value):el.value;calculate();}));
    dedicatedList.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{dedicated.splice(Number(b.dataset.remove),1);renderDedicated();calculate();});
  }
  root.querySelector('#add-dedicated').onclick=()=>{dedicated.push({category:'generic',label:'',quantity:1,powerW:0,fp:.9,fu:1,fs:1,isEstimated:true});renderDedicated();calculate();};
  function calculate(){const input=read(),r=calculateDPMS(input);Object.entries(r.circuitCounts).forEach(([k,v])=>{const o=form.querySelector(`[data-circuits="${k}"]`);if(o)o.textContent=v;});const options=gradeRules[r.grade]||[];gradePanel.innerHTML=r.grade?`<div class="dpms-grade"><b>Grado de electrificación: ${esc(r.grade)}</b><span>Superficie de aplicación: ${fmt(r.applicationArea)} m²</span><label>Distribución mínima de circuitos<select name="gradeVariant">${options.map((x,i)=>`<option value="${i}" ${i===input.scope.variant?'selected':''}>${esc(x.label)}</option>`).join('')}</select></label><small>AEA 770.8.3.1, Tabla 770.8.I, 770.8.3.2 y Tabla 770.8.II. La aplicación de estos grados en viviendas está condicionada a corriente asignada ≤ 63 A e Icc presunta ≤ 10 kA; esta versión todavía no verifica esos dos límites.</small></div>`: `<div class="dpms-note">${(dwelling||(buildingType&&input.scope.scopeMode==='unit'))?'No se puede determinar el grado: falta la superficie cubierta correspondiente al alcance seleccionado. Revisá la ficha del inmueble o completá este dato para este cálculo.':'El grado de electrificación por superficie de vivienda no aplica automáticamente a este tipo de inmueble.'}</div>`;
    const min=r.minimum;const minMsg=r.grade?`<p class="${min.compliant?'dpms-note':'dpms-warning'}"><b>Verificación de circuitos mínimos:</b> ${min.actualTotal} calculados / ${min.requiredTotal} mínimos para grado ${esc(r.grade)}. ${min.compliant?'Cumple la cantidad mínima seleccionada.':'Revisar la distribución mínima exigida.'}</p>`:'';
    results.innerHTML=`<div class="dpms-kpis"><div><span>Potencia aparente</span><strong>${fmt(r.totalVA)} VA</strong><small>${fmt(r.apparentKVA,3)} kVA</small></div><div><span>Potencia activa estimada</span><strong>${fmt(r.activeW)} W</strong><small>${fmt(r.activeKW,3)} kW</small></div><div><span>Corriente equivalente</span><strong>${fmt(r.currentA)} A</strong><small>${r.currentMethod} · ${fmt(r.voltage)} V</small></div><div><span>Grado de electrificación</span><strong>${esc(r.grade||(input.scope.isDwelling?'Falta superficie':'No aplica al alcance'))}</strong><small>${fmt(r.applicationArea)} m² de aplicación</small></div><div><span>Circuitos finales UG/UE</span><strong>${fmt(r.circuitCount,0)}</strong><small>FS aplicado: ${r.cs==null?'No definido':fmt(r.cs,2)} · ${fmt(r.circuitCount,0)} circuitos UG/UE</small></div></div><div class="dpms-formula"><b>Expresión de cálculo</b><div>DPMS = (Σ S<sub>UG/UE</sub> × FS) + Σ (P<sub>n</sub> / FP × FU × FS)</div><small>Primer término: demanda de referencia de circuitos generales y especiales, afectada por el coeficiente de simultaneidad de la Tabla 770.9.II. Segundo término: cargas específicas, con sus factores propios (AEA 770.9.1 y 770.9.2.1).</small><div class="dpms-formula-values">Demanda UG/UE: ${fmt(r.breakdown.generalInstalledVA)} VA × ${r.cs==null?'—':fmt(r.cs,2)} = ${fmt(r.breakdown.generalDemandVA)} VA · Cargas específicas: ${fmt(r.breakdown.dedicatedDemandVA)} VA</div></div>${minMsg}<p class="dpms-warning">La corriente trifásica es equivalente para carga equilibrada. Para dimensionar el alimentador con circuitos monofásicos y trifásicos se debe realizar la distribución por línea según AEA 770.9.3.1.</p>`;
    const rows=r.circuitDetails.map(x=>x.kind==='specific'?`<tr><td>${esc(x.name)}</td><td>${fmt(x.quantity,0)}</td><td>${fmt(x.activeW)} W</td><td>${fmt(x.apparentVA)} VA</td><td>${fmt(x.fp,2)}</td><td>${fmt(x.fu,2)}</td><td>${fmt(x.fs,2)}</td><td>${fmt(x.demandVA)} VA</td><td>${fmt(x.dpmsVA)} VA</td></tr>`:`<tr><td>${esc(x.name)}</td><td>${fmt(x.bocas,0)}</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>${fmt(x.demandVA)} VA</td><td>${fmt(x.dpmsVA)} VA</td></tr>`).join('');circuitDetail.innerHTML=`<div class="dpms-table-wrap"><table class="data-table"><thead><tr><th>Circuito / carga</th><th>Bocas / cant.</th><th>Potencia activa</th><th>Potencia aparente</th><th>FP</th><th>FU</th><th>FS</th><th>Demanda base</th><th>Demanda DPMS</th></tr></thead><tbody>${rows||'<tr><td colspan="9">Sin circuitos cargados</td></tr>'}</tbody></table></div>`;return {input,result:r};}
  form.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{if(el.name==='supply'&&el.value==='three'&&form.elements.voltage.value==='220')form.elements.voltage.value='380';if(el.name==='supply'&&el.value==='single'&&form.elements.voltage.value==='380')form.elements.voltage.value='220';calculate();}));
  form.addEventListener('change',e=>{if(e.target.name==='gradeVariant')calculate();if(e.target.name==='scopeMode'){const unit=e.target.value==='unit';const ca=unit?(property?.unitCoveredArea??(unitLike?property?.coveredArea:'')):(property?.coveredArea??'');const sa=unit?(property?.unitSemiCoveredArea??(unitLike?property?.semiCoveredArea:'')):(property?.semiCoveredArea??'');form.elements.coveredArea.value=ca??'';form.elements.semiCoveredArea.value=sa??'';calculate();}});
  const selectedVD=vdSaved.find(x=>x.result?.dpms?.recordId===selectedDPMSId);if(selectedVD){vdInstallation.value=selectedVD.input.installation;vdDistance.value=selectedVD.input.distance;vdLimit.value=selectedVD.input.limit;vdShowSaved(selectedVD);}else{vdPaint();}vdRenderHistory();
  function paintHistory(){const box=root.querySelector('#dpms-history');box.innerHTML=saved.length?saved.map(x=>`<div class="history-row"><div><strong>${new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(x.updatedAt||x.createdAt))}</strong><small>${fmt(x.result.totalVA)} VA · ${fmt(x.result.currentA)} A · ${esc(x.result.grade||'Grado no determinado')} · ${fmt(x.result.circuitCount,0)} circuitos · FS ${x.result.cs==null?'—':fmt(x.result.cs,2)} · ${esc(x.input.scope?.scopeLabel||'')}</small></div><div class="history-actions"><button type="button" class="secondary" data-view="${esc(x.id)}">Ver</button><button type="button" class="secondary" data-edit="${esc(x.id)}">Editar</button><button type="button" class="danger" data-delete-calculation="${esc(x.id)}">Eliminar</button></div></div>`).join(''):'<p class="muted">Todavía no hay cálculos guardados.</p>';box.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>openSaved(b.dataset.view));box.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>restoreSaved(b.dataset.edit,true));box.querySelectorAll('[data-delete-calculation]').forEach(b=>b.onclick=async()=>{const rec=saved.find(x=>x.id===b.dataset.deleteCalculation);if(!rec)return;const stamp=new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(rec.createdAt));if(!confirm(`¿Eliminar definitivamente SOLO este cálculo (${stamp})? No se eliminará el trabajo ni los demás cálculos.`))return;b.disabled=true;try{await remove('dpms_calculations',rec.id);const idx=saved.findIndex(x=>x.id===rec.id);if(idx>=0)saved.splice(idx,1);if(selectedDPMSId===rec.id)selectedDPMSId=saved[0]?.id||null;paintHistory();paintCurrent();if(!saved.length)showForm(true);else{const attached=vdSaved.find(x=>x.result?.dpms?.recordId===selectedDPMSId);if(attached)vdShowSaved(attached);else vdPaint();}}catch(err){b.disabled=false;alert('No se pudo eliminar el cálculo. No se modificó el historial. Detalle: '+(err?.message||err));}});}
  function openSaved(id){const rec=saved.find(x=>x.id===id);if(!rec)return;selectedDPMSId=id;editingId=null;paintCurrent();showForm(false);const attached=vdSaved.find(x=>x.result?.dpms?.recordId===id);if(attached){vdInstallation.value=attached.input.installation;vdDistance.value=attached.input.distance;vdLimit.value=attached.input.limit;vdShowSaved(attached);}else{vdInstallation.value='aerial';vdDistance.value='';vdLimit.value=3;vdPaint();}currentPanel.scrollIntoView({behavior:'smooth',block:'start'});}
  function restoreSaved(id,edit=true){const rec=saved.find(x=>x.id===id);if(!rec)return;selectedDPMSId=id;editingId=edit?id:null;const attached=vdSaved.find(x=>x.result?.dpms?.recordId===id);if(attached){vdInstallation.value=attached.input.installation;vdDistance.value=attached.input.distance;vdLimit.value=attached.input.limit;vdShowSaved(attached);}else{vdInstallation.value='aerial';vdDistance.value='';vdLimit.value=3;vdPaint();}const i=rec.input;for(const [k,v] of Object.entries({supply:i.supply,voltage:i.voltage,fp:i.fp,scopeMode:i.scope?.scopeMode||'full',scopeLabel:i.scope?.scopeLabel||'',coveredArea:i.scope?.coveredArea??'',semiCoveredArea:i.scope?.semiCoveredArea??'',iugSimpleBocas:i.circuits.iugSimpleBocas,iugDerivedBocas:i.circuits.iugDerivedBocas,tugBocas:i.circuits.tugBocas,iueBocas:i.circuits.iueBocas,tueBocas:i.circuits.tueBocas,gradeVariant:i.scope?.variant||0})){if(form.elements[k])form.elements[k].value=v;}dedicated=JSON.parse(JSON.stringify(i.dedicated||[]));renderDedicated();calculate();form.querySelector('#dpms-save').textContent=editingId?'Guardar cambios':'Guardar como nuevo cálculo';showForm(true);form.scrollIntoView({behavior:'smooth',block:'start'});}
  form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const {input,result}=calculate();const previous=editingId?saved.find(x=>x.id===editingId):null;const now=new Date().toISOString();const record={...(previous||{}),id:previous?.id||uid(),jobId:job.id,createdAt:previous?.createdAt||now,updatedAt:now,modelVersion:'dpms-0.5.6',propertyId:property?.id||null,propertySnapshot:property?JSON.parse(JSON.stringify(property)):null,input:JSON.parse(JSON.stringify(input)),result:JSON.parse(JSON.stringify(result))};await put('dpms_calculations',record);const idx=saved.findIndex(x=>x.id===record.id);if(idx>=0)saved[idx]=record;else saved.unshift(record);saved.sort((a,b)=>(b.updatedAt||b.createdAt).localeCompare(a.updatedAt||a.createdAt));selectedDPMSId=record.id;editingId=null;paintHistory();paintCurrent();showForm(false);vdPaint();});
  renderDedicated();calculate();paintHistory();paintCurrent();if(saved.length)showForm(false);
}
